mapper.update:
UPDATE vaccine
name = #{name}, category_id = #{categoryId}, manufacturer = #{manufacturer}, price = #{price}, stock = #{stock}, doses = #{doses}, interval_days = #{intervalDays}, target_group = #{targetGroup}, contraindication = #{contraindication}, description = #{description}, image = #{image}, status = #{status},
WHERE id = #{id}

mapper.select:
SELECT v.*, c.name as category_name FROM vaccine v LEFT JOIN vaccine_category c ON v.category_id = c.id -- 这里 LEFT JOIN vaccine_category 把分类名称 categoryName 一起查出来，映射到 Vaccine 实体的非数据库字段。
AND v.name LIKE CONCAT('%', #{name}, '%') AND v.category_id = #{categoryId} AND v.status = #{status}
ORDER BY v.create_time DESC

SELECT COUNT(*) FROM vaccine v

    AND v.name LIKE CONCAT('%', #{name}, '%')
    AND v.category_id = #{categoryId}
    AND v.status = #{status}
